import{_ as e,o,c as t,a2 as n}from"./chunks/framework.C0KMm31j.js";const c="/Nav2ArticlesSite/article-assets/2026-07-14/nav2_bt_navigator_cover.png",r="/Nav2ArticlesSite/article-assets/2026-07-14/bt_nav_01_lifecycle.png",i="/Nav2ArticlesSite/article-assets/2026-07-14/bt_nav_02_goal_ingress.png",s="/Nav2ArticlesSite/article-assets/2026-07-14/bt_nav_03_tree_build.png",l="/Nav2ArticlesSite/article-assets/2026-07-14/bt_nav_04_single_pose.png",d="/Nav2ArticlesSite/article-assets/2026-07-14/bt_nav_05_multi_pose.png",p="/Nav2ArticlesSite/article-assets/2026-07-14/bt_nav_06_recovery_feedback.png",P=JSON.parse('{"title":"一条导航目标如何指挥整套 Nav2？拆解 nav2_bt_navigator 全数据流","description":"向 RViz 发送一个导航目标后，全局规划、路径跟踪、代价地图清理、原地旋转和失败重试看似是一条自动运转的链路。但这些模块并不知道“导航任务”的全局进度，真正把它们组织成一个完整任务的是 nav2btnavigator。","frontmatter":{"title":"一条导航目标如何指挥整套 Nav2？拆解 `nav2_bt_navigator` 全数据流","description":"向 RViz 发送一个导航目标后，全局规划、路径跟踪、代价地图清理、原地旋转和失败重试看似是一条自动运转的链路。但这些模块并不知道“导航任务”的全局进度，真正把它们组织成一个完整任务的是 nav2btnavigator。","date":"2026-07-14","topic":"Nav2 工程实践","section":"一 · 架构与启动","readingTime":9,"source":"2026-07-14/nav2_bt_navigator_full_dataflow.md","status":"published","cover":"/article-assets/2026-07-14/nav2_bt_navigator_cover.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-bt-navigator-full-dataflow"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"一条导航目标如何指挥整套 Nav2？拆解 `nav2_bt_navigator` 全数据流"}],["meta",{"property":"og:description","content":"向 RViz 发送一个导航目标后，全局规划、路径跟踪、代价地图清理、原地旋转和失败重试看似是一条自动运转的链路。但这些模块并不知道“导航任务”的全局进度，真正把它们组织成一个完整任务的是 nav2btnavigator。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-bt-navigator-full-dataflow"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-14/nav2_bt_navigator_cover.png"}],["meta",{"property":"article:published_time","content":"2026-07-14"}],["meta",{"name":"twitter:title","content":"一条导航目标如何指挥整套 Nav2？拆解 `nav2_bt_navigator` 全数据流"}],["meta",{"name":"twitter:description","content":"向 RViz 发送一个导航目标后，全局规划、路径跟踪、代价地图清理、原地旋转和失败重试看似是一条自动运转的链路。但这些模块并不知道“导航任务”的全局进度，真正把它们组织成一个完整任务的是 nav2btnavigator。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-14/nav2_bt_navigator_cover.png"}]],"prev":{"text":"一条 `/cmd_vel` 是怎样诞生的？从 `entry.launch.py` 拆解 Nav2 全数据流","link":"/nav2/myworld-bringup-entry-full-dataflow"},"next":{"text":"Nav2 为什么能边规划边控制？拆解 `nav2_behavior_tree` 调用全数据流","link":"/nav2/nav2-behavior-tree-full-dataflow"}},"headers":[],"relativePath":"nav2/nav2-bt-navigator-full-dataflow.md","filePath":"nav2/nav2-bt-navigator-full-dataflow.md","lastUpdated":null}'),h={name:"nav2/nav2-bt-navigator-full-dataflow.md"};function _(b,a,v,u,g,m){return o(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="一条导航目标如何指挥整套-nav2-拆解-nav2-bt-navigator-全数据流" tabindex="-1">一条导航目标如何指挥整套 Nav2？拆解 <code>nav2_bt_navigator</code> 全数据流 <a class="header-anchor" href="#一条导航目标如何指挥整套-nav2-拆解-nav2-bt-navigator-全数据流" aria-label="Permalink to &quot;一条导航目标如何指挥整套 Nav2？拆解 `nav2_bt_navigator` 全数据流&quot;">​</a></h1><p><img src="'+c+'" alt="nav2_bt_navigator 全数据流封面"></p><p>向 RViz 发送一个导航目标后，全局规划、路径跟踪、代价地图清理、原地旋转和失败重试看似是一条自动运转的链路。但这些模块并不知道“导航任务”的全局进度，真正把它们组织成一个完整任务的是 <code>nav2_bt_navigator</code>。</p><p><code>bt_navigator</code> 不计算路径，也不生成速度。它是 Nav2 的任务编排中枢：对外提供导航 Action，对内加载 XML 行为树，通过 blackboard 在树节点间传递目标和路径，再用 Action 或 Service 调用 planner、controller、costmap 和 behavior server。</p><p>本文按照真实数据流，从节点启动一直拆到结果返回。</p><h2 id="一、bt-navigator-在-nav2-中站在哪里" tabindex="-1">一、bt_navigator 在 Nav2 中站在哪里 <a class="header-anchor" href="#一、bt-navigator-在-nav2-中站在哪里" aria-label="Permalink to &quot;一、bt_navigator 在 Nav2 中站在哪里&quot;">​</a></h2><p><code>navigation_launch.py</code> 会以独立进程或 Component 方式启动 <code>bt_navigator</code>，并把它交给 <code>lifecycle_manager_navigation</code> 管理。因此它不是一启动就立即接任务，而是先经过 configure 和 activate。</p><p><img src="'+r+`" alt="bt_navigator 生命周期与内部组件"></p><h3 id="_1-1-构造阶段" tabindex="-1">1.1 构造阶段 <a class="header-anchor" href="#_1-1-构造阶段" aria-label="Permalink to &quot;1.1 构造阶段&quot;">​</a></h3><p>构造阶段声明默认参数和 49 个 BT 插件库。这些库覆盖四类能力。</p><h4 id="_1-1-1-action-节点" tabindex="-1">1.1.1 Action 节点 <a class="header-anchor" href="#_1-1-1-action-节点" aria-label="Permalink to &quot;1.1.1 Action 节点&quot;">​</a></h4><p>例如 <code>ComputePathToPose</code>、<code>FollowPath</code>、<code>Spin</code>、<code>Wait</code> 和 <code>BackUp</code>。</p><h4 id="_1-1-2-condition-节点" tabindex="-1">1.1.2 Condition 节点 <a class="header-anchor" href="#_1-1-2-condition-节点" aria-label="Permalink to &quot;1.1.2 Condition 节点&quot;">​</a></h4><p>例如 <code>GoalUpdated</code>、<code>GoalReached</code>、<code>IsStuck</code> 和 <code>IsPathValid</code>。</p><h4 id="_1-1-3-control-节点" tabindex="-1">1.1.3 Control 节点 <a class="header-anchor" href="#_1-1-3-control-节点" aria-label="Permalink to &quot;1.1.3 Control 节点&quot;">​</a></h4><p>例如 <code>RecoveryNode</code>、<code>PipelineSequence</code> 和 <code>RoundRobin</code>。</p><h4 id="_1-1-4-decorator-节点" tabindex="-1">1.1.4 Decorator 节点 <a class="header-anchor" href="#_1-1-4-decorator-节点" aria-label="Permalink to &quot;1.1.4 Decorator 节点&quot;">​</a></h4><p>例如 <code>RateController</code>、<code>DistanceController</code> 和 <code>SpeedController</code>。</p><h3 id="_1-2-configure-阶段" tabindex="-1">1.2 Configure 阶段 <a class="header-anchor" href="#_1-2-configure-阶段" aria-label="Permalink to &quot;1.2 Configure 阶段&quot;">​</a></h3><p>Configure 阶段创建 TF Buffer、TransformListener 和 <code>OdomSmoother</code>，然后配置两个导航器：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NavigateToPoseNavigator</span></span>
<span class="line"><span>  → /navigate_to_pose</span></span>
<span class="line"><span></span></span>
<span class="line"><span>NavigateThroughPosesNavigator</span></span>
<span class="line"><span>  → /navigate_through_poses</span></span></code></pre></div><p>两者各有一个 <code>BtActionServer</code>、一棵行为树和一份 blackboard，但共享 TF、平滑里程计和 <code>NavigatorMuxer</code>。这个 muxer 保证同一时刻只有一种导航任务在运行，避免单目标和多目标任务同时指挥底层服务器。</p><h3 id="_1-3-activate-阶段" tabindex="-1">1.3 Activate 阶段 <a class="header-anchor" href="#_1-3-activate-阶段" aria-label="Permalink to &quot;1.3 Activate 阶段&quot;">​</a></h3><p>Activate 阶段加载默认 XML，激活两个 Action Server，并与 lifecycle manager 建立 bond。到这一步，节点才真正进入可接收任务的 ACTIVE 状态。</p><h2 id="二、导航目标如何进入行为树" tabindex="-1">二、导航目标如何进入行为树 <a class="header-anchor" href="#二、导航目标如何进入行为树" aria-label="Permalink to &quot;二、导航目标如何进入行为树&quot;">​</a></h2><p><code>bt_navigator</code> 有三种常见入口：单目标 Action、多目标 Action，以及 RViz 使用的 <code>goal_pose</code> topic。</p><p><img src="`+i+'" alt="单目标与多目标任务入口"></p><h3 id="_2-1-action-入口" tabindex="-1">2.1 Action 入口 <a class="header-anchor" href="#_2-1-action-入口" aria-label="Permalink to &quot;2.1 Action 入口&quot;">​</a></h3><p>Action 客户端可以直接发送 <code>NavigateToPose</code> 或 <code>NavigateThroughPoses</code>。单目标消息包含一个 <code>PoseStamped</code> 和可选的 <code>behavior_tree</code> 文件路径；多目标消息则包含一组 <code>PoseStamped</code> 和可选 XML 路径。</p><h3 id="_2-2-rviz-goal-pose-入口" tabindex="-1">2.2 RViz <code>goal_pose</code> 入口 <a class="header-anchor" href="#_2-2-rviz-goal-pose-入口" aria-label="Permalink to &quot;2.2 RViz `goal_pose` 入口&quot;">​</a></h3><p>RViz 发布 <code>goal_pose</code> 时，<code>NavigateToPoseNavigator</code> 不会绕开 Action 机制直接改行为树。它会把 topic 消息封装成 <code>NavigateToPose::Goal</code>，再通过自己的 Action Client 发给 <code>/navigate_to_pose</code>。因此来自 RViz 和来自调度系统的单目标，最终走的是同一条执行链。</p><h3 id="_2-3-写入-blackboard" tabindex="-1">2.3 写入 Blackboard <a class="header-anchor" href="#_2-3-写入-blackboard" aria-label="Permalink to &quot;2.3 写入 Blackboard&quot;">​</a></h3><p>目标通过 muxer 检查后，导航器把任务数据写入 blackboard：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>单目标：blackboard[&quot;goal&quot;]  = PoseStamped</span></span>\n<span class="line"><span>多目标：blackboard[&quot;goals&quot;] = PoseStamped[]</span></span>\n<span class="line"><span>共享路径：blackboard[&quot;path&quot;]  = nav_msgs/Path</span></span></code></pre></div><p>每个新任务还会清零 <code>number_recoveries</code>，记录开始时间，并根据 Goal 中的 <code>behavior_tree</code> 字段决定使用默认 XML 还是任务指定 XML。</p><h2 id="三、xml-为什么能变成可执行的-ros-2-流程" tabindex="-1">三、XML 为什么能变成可执行的 ROS 2 流程 <a class="header-anchor" href="#三、xml-为什么能变成可执行的-ros-2-流程" aria-label="Permalink to &quot;三、XML 为什么能变成可执行的 ROS 2 流程&quot;">​</a></h2><p>XML 只是树结构的文本描述。真正让 <code>&lt;ComputePathToPose&gt;</code> 这样的标签具备 ROS 2 能力的，是 <code>nav2_behavior_tree::BehaviorTreeEngine</code> 和动态插件库。</p><p><img src="'+s+`" alt="XML、插件库与 blackboard 组成行为树"></p><h3 id="_3-1-加载并注册-bt-插件" tabindex="-1">3.1 加载并注册 BT 插件 <a class="header-anchor" href="#_3-1-加载并注册-bt-插件" aria-label="Permalink to &quot;3.1 加载并注册 BT 插件&quot;">​</a></h3><p><code>BehaviorTreeEngine</code> 构造时逐个加载 <code>plugin_lib_names</code>，每个动态库通过 <code>BT_REGISTER_NODES</code> 向 <code>BehaviorTreeFactory</code> 注册自己的标签名和节点构造方法。</p><h3 id="_3-2-解析-xml-并创建节点" tabindex="-1">3.2 解析 XML 并创建节点 <a class="header-anchor" href="#_3-2-解析-xml-并创建节点" aria-label="Permalink to &quot;3.2 解析 XML 并创建节点&quot;">​</a></h3><p>当 <code>BtActionServer</code> 读取 XML 后，<code>createTreeFromText()</code> 按标签找到已注册类型，创建真实节点对象，再把同一份 blackboard 交给它们。blackboard 中不只有目标和路径，还包含：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node                     BT 节点共用的 ROS 2 Client Node</span></span>
<span class="line"><span>tf_buffer                当前位姿查询</span></span>
<span class="line"><span>odom_smoother            平滑后的机器人速度</span></span>
<span class="line"><span>server_timeout           单次 Action / Service 等待超时</span></span>
<span class="line"><span>bt_loop_duration         BT 主循环周期</span></span>
<span class="line"><span>wait_for_service_timeout 等待底层服务就绪的超时</span></span>
<span class="line"><span>number_recoveries        已执行恢复动作次数</span></span></code></pre></div><h3 id="_3-3-周期-tick-行为树" tabindex="-1">3.3 周期 Tick 行为树 <a class="header-anchor" href="#_3-3-周期-tick-行为树" aria-label="Permalink to &quot;3.3 周期 Tick 行为树&quot;">​</a></h3><p>当前参数中 <code>bt_loop_duration=10 ms</code>，表示行为树决策主循环最快约以 <code>100 Hz</code> 调用 <code>tickRoot()</code>。这不等于全局规划也以 100 Hz 运行，因为 XML 中的 <code>RateController</code> 还会对规划分支单独限频。</p><h3 id="_3-4-判断是否重新加载-xml" tabindex="-1">3.4 判断是否重新加载 XML <a class="header-anchor" href="#_3-4-判断是否重新加载-xml" aria-label="Permalink to &quot;3.4 判断是否重新加载 XML&quot;">​</a></h3><p>同一 XML 已加载且 <code>always_reload_bt_xml=false</code> 时，新任务会复用当前树；传入不同 XML，或显式开启 always reload，才会重新解析和构建。</p><h2 id="四、单目标如何变成路径跟踪任务" tabindex="-1">四、单目标如何变成路径跟踪任务 <a class="header-anchor" href="#四、单目标如何变成路径跟踪任务" aria-label="Permalink to &quot;四、单目标如何变成路径跟踪任务&quot;">​</a></h2><h3 id="_4-1-加载默认单目标主链" tabindex="-1">4.1 加载默认单目标主链 <a class="header-anchor" href="#_4-1-加载默认单目标主链" aria-label="Permalink to &quot;4.1 加载默认单目标主链&quot;">​</a></h3><p>默认单目标行为树是 <code>navigate_to_pose_w_replanning_and_recovery.xml</code>。主链由 <code>RecoveryNode → PipelineSequence → RateController → ComputePathToPose → FollowPath</code> 组成。</p><p><img src="`+l+'" alt="NavigateToPose 默认行为树主数据流"></p><h3 id="_4-2-调用-planner-server" tabindex="-1">4.2 调用 Planner Server <a class="header-anchor" href="#_4-2-调用-planner-server" aria-label="Permalink to &quot;4.2 调用 Planner Server&quot;">​</a></h3><p>每次规划时，<code>ComputePathToPose</code> 从 <code>blackboard[goal]</code> 取出目标，组装 <code>nav2_msgs/action/ComputePathToPose</code> Goal，发给 planner server 的 <code>/compute_path_to_pose</code>。</p><p>默认 XML 传入 <code>planner_id=&quot;GridBased&quot;</code>。当前项目又在 planner server 中增加了 <code>selected_planner</code>：如果该参数非空，planner server 会优先使用它，因此实际插件可以由服务端统一覆盖 XML 中的 <code>GridBased</code>。</p><h3 id="_4-3-写入-path-并调用-controller-server" tabindex="-1">4.3 写入 Path 并调用 Controller Server <a class="header-anchor" href="#_4-3-写入-path-并调用-controller-server" aria-label="Permalink to &quot;4.3 写入 Path 并调用 Controller Server&quot;">​</a></h3><p>规划成功后，<code>ComputePathToPose</code> 把返回的 <code>nav_msgs/Path</code> 写入 <code>blackboard[path]</code>。<code>FollowPath</code> 在下一分支读取该路径，发送 <code>nav2_msgs/action/FollowPath</code> 给 controller server。</p><h3 id="_4-4-选择-controller-插件" tabindex="-1">4.4 选择 Controller 插件 <a class="header-anchor" href="#_4-4-选择-controller-插件" aria-label="Permalink to &quot;4.4 选择 Controller 插件&quot;">​</a></h3><p>默认 XML 把 <code>controller_id</code> 留空。本项目的 <code>FollowPathAction</code> 在发现 ID 为空时，会读取 <code>bt_navigator.selected_controller</code>。因此实车参数可选 <code>DWB</code>，仿真参数可选 <code>TEB</code>，而不需要修改默认 XML。</p><h3 id="_4-5-pipelinesequence-周期重规划" tabindex="-1">4.5 PipelineSequence 周期重规划 <a class="header-anchor" href="#_4-5-pipelinesequence-周期重规划" aria-label="Permalink to &quot;4.5 PipelineSequence 周期重规划&quot;">​</a></h3><p><code>PipelineSequence</code> 是这条数据流的关键。普通 Sequence 进入后一个 RUNNING 子节点后，不会继续 tick 前面已成功的节点；PipelineSequence 则会在 <code>FollowPath</code> 跟踪当前路径时，继续回头 tick 规划分支。<code>RateController hz=&quot;1.0&quot;</code> 将重规划限制为 <code>1 Hz</code>，新 Path 写入 blackboard 后，<code>FollowPath</code> 检测到路径变化并更新正在执行的 controller Goal。</p><h2 id="五、多目标导航不是简单循环单目标" tabindex="-1">五、多目标导航不是简单循环单目标 <a class="header-anchor" href="#五、多目标导航不是简单循环单目标" aria-label="Permalink to &quot;五、多目标导航不是简单循环单目标&quot;">​</a></h2><p>默认多目标树是 <code>navigate_through_poses_w_replanning_and_recovery.xml</code>。它与单目标共享控制和恢复框架，但规划分支不同。</p><p><img src="'+d+`" alt="NavigateThroughPoses 多目标数据流"></p><h3 id="_5-1-移除已经经过的目标" tabindex="-1">5.1 移除已经经过的目标 <a class="header-anchor" href="#_5-1-移除已经经过的目标" aria-label="Permalink to &quot;5.1 移除已经经过的目标&quot;">​</a></h3><p>它先用 <code>RemovePassedGoals radius=&quot;0.7&quot;</code> 删除已经经过的目标点，再把剩余序列写回 <code>blackboard[goals]</code>。随后 <code>ComputePathThroughPoses</code> 一次性把剩余目标交给 <code>/compute_path_through_poses</code>，生成一条贯穿多个目标的全局 Path。</p><h3 id="_5-2-限制多目标重规划频率" tabindex="-1">5.2 限制多目标重规划频率 <a class="header-anchor" href="#_5-2-限制多目标重规划频率" aria-label="Permalink to &quot;5.2 限制多目标重规划频率&quot;">​</a></h3><p>多目标树的 <code>RateController</code> 是 <code>0.333 Hz</code>，约每 3 秒重规划一次。它比单目标的 1 Hz 更低，可以避免较长的多段路径过于频繁地重算。</p><h3 id="_5-3-保持连续的多目标任务" tabindex="-1">5.3 保持连续的多目标任务 <a class="header-anchor" href="#_5-3-保持连续的多目标任务" aria-label="Permalink to &quot;5.3 保持连续的多目标任务&quot;">​</a></h3><p>这种设计与 waypoint follower 的“一个点完成后再发下一个单目标”不同。<code>NavigateThroughPoses</code> 保持一个连续 Action，让 planner 同时看到剩余目标序列，也让反馈中能持续返回 <code>number_of_poses_remaining</code>。</p><h2 id="六、规划或控制失败后-行为树如何分层恢复" tabindex="-1">六、规划或控制失败后，行为树如何分层恢复 <a class="header-anchor" href="#六、规划或控制失败后-行为树如何分层恢复" aria-label="Permalink to &quot;六、规划或控制失败后，行为树如何分层恢复&quot;">​</a></h2><p>默认树不会一遇到错误就立即判定导航失败。它有两层恢复。</p><h3 id="_6-1-上下文恢复" tabindex="-1">6.1 上下文恢复 <a class="header-anchor" href="#_6-1-上下文恢复" aria-label="Permalink to &quot;6.1 上下文恢复&quot;">​</a></h3><p><code>ComputePathToPose</code> 或 <code>ComputePathThroughPoses</code> 失败时，先调用 <code>global_costmap/clear_entirely_global_costmap</code>，再重试一次规划。<code>FollowPath</code> 失败时，先清理 local costmap，再重试跟踪。</p><h3 id="_6-2-系统级恢复" tabindex="-1">6.2 系统级恢复 <a class="header-anchor" href="#_6-2-系统级恢复" aria-label="Permalink to &quot;6.2 系统级恢复&quot;">​</a></h3><p>上下文恢复仍失败后，顶层 <code>RecoveryNode</code> 进入 <code>RecoveryFallback</code>。它先检查 <code>GoalUpdated</code>；如果上层已经换了目标，就不必继续恢复旧任务。否则 <code>RoundRobin</code> 按顺序尝试：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>清理 local + global costmap</span></span>
<span class="line"><span>  → Spin 1.57 rad</span></span>
<span class="line"><span>  → Wait 5 s</span></span>
<span class="line"><span>  → BackUp 0.30 m，0.05 m/s</span></span></code></pre></div><p>一个恢复动作成功后，树回到主导航分支重试。顶层 <code>number_of_retries=&quot;6&quot;</code>，表示默认树最多允许 6 轮系统级恢复；超过后整棵树返回 FAILURE。</p><h2 id="七、反馈、抢占、取消和最终结果如何回到上层" tabindex="-1">七、反馈、抢占、取消和最终结果如何回到上层 <a class="header-anchor" href="#七、反馈、抢占、取消和最终结果如何回到上层" aria-label="Permalink to &quot;七、反馈、抢占、取消和最终结果如何回到上层&quot;">​</a></h2><p><img src="`+p+`" alt="恢复、抢占、取消与反馈闭环"></p><h3 id="_7-1-生成-action-feedback" tabindex="-1">7.1 生成 Action Feedback <a class="header-anchor" href="#_7-1-生成-action-feedback" aria-label="Permalink to &quot;7.1 生成 Action Feedback&quot;">​</a></h3><p>每轮 <code>tickRoot()</code> 后，<code>BtActionServer</code> 调用导航器的 <code>onLoop()</code> 生成 Action Feedback。单目标和多目标反馈都包含：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>current_pose</span></span>
<span class="line"><span>navigation_time</span></span>
<span class="line"><span>estimated_time_remaining</span></span>
<span class="line"><span>number_of_recoveries</span></span>
<span class="line"><span>distance_remaining</span></span></code></pre></div><p>多目标反馈还包含 <code>number_of_poses_remaining</code>。</p><h3 id="_7-2-计算剩余距离与时间" tabindex="-1">7.2 计算剩余距离与时间 <a class="header-anchor" href="#_7-2-计算剩余距离与时间" aria-label="Permalink to &quot;7.2 计算剩余距离与时间&quot;">​</a></h3><p>当前位姿来自 <code>global_frame → robot_base_frame</code> TF。剩余距离不是直线距离，而是先在 <code>blackboard[path]</code> 中找到最靠近当前位姿的路径点，再累加该点到路径末端的长度。预计剩余时间由这个距离除以 <code>OdomSmoother</code> 给出的当前线速度；只有速度大于 <code>0.01 m/s</code> 且剩余距离大于 <code>0.1 m</code> 时才会计算。</p><h3 id="_7-3-处理任务抢占" tabindex="-1">7.3 处理任务抢占 <a class="header-anchor" href="#_7-3-处理任务抢占" aria-label="Permalink to &quot;7.3 处理任务抢占&quot;">​</a></h3><p>抢占不是无条件换树。待处理目标与当前任务使用同一 XML 时，导航器可以直接接受 pending goal，更新 <code>goal</code> 或 <code>goals</code> blackboard，让当前树继续运行。如果新目标要求不同 XML，则拒绝真抢占；上层应先取消旧任务，再发送新任务。</p><h3 id="_7-4-传播取消与停止信号" tabindex="-1">7.4 传播取消与停止信号 <a class="header-anchor" href="#_7-4-传播取消与停止信号" aria-label="Permalink to &quot;7.4 传播取消与停止信号&quot;">​</a></h3><p>取消、Action Server 失活或 ROS 关闭时，<code>BehaviorTreeEngine</code> 调用 <code>halt()</code> 向整棵树传播停止信号。所有仍处于 RUNNING 的 Action 节点都必须被终止，否则上层已经显示“已取消”，底层 controller 或 recovery 仍可能继续运动机器人。</p><h3 id="_7-5-返回最终结果" tabindex="-1">7.5 返回最终结果 <a class="header-anchor" href="#_7-5-返回最终结果" aria-label="Permalink to &quot;7.5 返回最终结果&quot;">​</a></h3><p>树根最终返回 SUCCESS、FAILURE 或收到取消后，<code>BtActionServer</code> 把它转换为 <code>SUCCEEDED</code>、<code>FAILED</code> 或 <code>CANCELED</code> Action 结果，停止所有残留节点，最后通过 <code>NavigatorMuxer</code> 释放导航占用状态。到这里，一个导航任务才算完整结束。</p><h2 id="八、完整数据流可以压缩成一条链" tabindex="-1">八、完整数据流可以压缩成一条链 <a class="header-anchor" href="#八、完整数据流可以压缩成一条链" aria-label="Permalink to &quot;八、完整数据流可以压缩成一条链&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RViz / 调度系统</span></span>
<span class="line"><span>  → NavigateToPose / NavigateThroughPoses</span></span>
<span class="line"><span>  → NavigatorMuxer 互斥检查</span></span>
<span class="line"><span>  → 目标写入 blackboard</span></span>
<span class="line"><span>  → 加载默认或任务指定 XML</span></span>
<span class="line"><span>  → BehaviorTreeEngine 周期 tickRoot()</span></span>
<span class="line"><span>  → ComputePath Action 调用 planner_server</span></span>
<span class="line"><span>  → Path 写回 blackboard</span></span>
<span class="line"><span>  → FollowPath Action 调用 controller_server</span></span>
<span class="line"><span>  → 失败时调用 costmap Service 和 behavior server</span></span>
<span class="line"><span>  → TF + /odom + Path 组合成 Action Feedback</span></span>
<span class="line"><span>  → SUCCEEDED / FAILED / CANCELED 返回上层</span></span></code></pre></div><p>这条链里，blackboard 是数据中心，XML 是流程规则，BT 插件是 ROS 2 适配层，<code>BehaviorTreeEngine</code> 是状态推进器，而 <code>BtActionServer</code> 则负责把整棵树包装成标准导航 Action。</p><h2 id="九、调试-bt-navigator-时最该查什么" tabindex="-1">九、调试 bt_navigator 时最该查什么 <a class="header-anchor" href="#九、调试-bt-navigator-时最该查什么" aria-label="Permalink to &quot;九、调试 bt_navigator 时最该查什么&quot;">​</a></h2><h3 id="_9-1-检查-action-入口" tabindex="-1">9.1 检查 Action 入口 <a class="header-anchor" href="#_9-1-检查-action-入口" aria-label="Permalink to &quot;9.1 检查 Action 入口&quot;">​</a></h3><p>确认 <code>/navigate_to_pose</code> 或 <code>/navigate_through_poses</code> 有活动服务端，并检查 Goal 中的 frame_id、时间戳和 <code>behavior_tree</code> 路径。</p><h3 id="_9-2-检查-xml-与插件是否匹配" tabindex="-1">9.2 检查 XML 与插件是否匹配 <a class="header-anchor" href="#_9-2-检查-xml-与插件是否匹配" aria-label="Permalink to &quot;9.2 检查 XML 与插件是否匹配&quot;">​</a></h3><p>XML 中任何标签没有对应动态库，或端口类型不匹配，都会在 <code>createTreeFromText()</code> 阶段失败，任务不会进入规划。</p><h3 id="_9-3-检查-blackboard-关键名" tabindex="-1">9.3 检查 Blackboard 关键名 <a class="header-anchor" href="#_9-3-检查-blackboard-关键名" aria-label="Permalink to &quot;9.3 检查 Blackboard 关键名&quot;">​</a></h3><p>XML 中的 <code>{goal}</code>、<code>{goals}</code> 和 <code>{path}</code> 必须与 <code>goal_blackboard_id</code>、<code>goals_blackboard_id</code> 和 <code>path_blackboard_id</code> 对应，否则节点之间传不到数据。</p><h3 id="_9-4-区分-bt-tick-频率与业务频率" tabindex="-1">9.4 区分 BT Tick 频率与业务频率 <a class="header-anchor" href="#_9-4-区分-bt-tick-频率与业务频率" aria-label="Permalink to &quot;9.4 区分 BT Tick 频率与业务频率&quot;">​</a></h3><p><code>bt_loop_duration=10 ms</code> 只代表决策轮询，规划频率还受 <code>RateController</code>、planner server 和代价地图更新频率限制。</p><h3 id="_9-5-按层排查机器人不动" tabindex="-1">9.5 按层排查机器人不动 <a class="header-anchor" href="#_9-5-按层排查机器人不动" aria-label="Permalink to &quot;9.5 按层排查机器人不动&quot;">​</a></h3><p>先看 BT 是否进入 <code>ComputePath</code>，再看 <code>path</code> 是否写回，然后看 <code>FollowPath</code> 是否 active，最后才看 <code>/cmd_vel</code>。只看速度 topic，无法区分“没收到目标”、“行为树未加载”、“规划失败”和“控制失败”。</p><h2 id="十、核心结论" tabindex="-1">十、核心结论 <a class="header-anchor" href="#十、核心结论" aria-label="Permalink to &quot;十、核心结论&quot;">​</a></h2><p><code>nav2_bt_navigator</code> 的价值不在于某一个算法，而在于它把导航系统从“节点集合”变成了“可描述、可替换、可恢复的任务流程”。</p><p>目标、路径和恢复计数通过 blackboard 流动；planner、controller 和 behavior server 通过 Action 被调度；XML 决定顺序、并行关系、重试次数和恢复策略；最终统一暴露为 <code>NavigateToPose</code> 和 <code>NavigateThroughPoses</code>。</p><p>所以，当需要改变 Nav2 的任务逻辑时，第一反应不应是修改 planner 或 controller，而是先判断：这是算法问题，还是行为树的数据流和恢复策略问题。</p>`,109)])])}const q=e(h,[["render",_]]);export{P as __pageData,q as default};
